const apiBase='/api';let allGames=[];let allMembers=[];let memberNameToId={};let currentStatusFilter='all';let currentPlayerFilters=new Set();function showToast(message,type='success'){const toast=document.getElementById('toast');toast.textContent=message;toast.className=`toast ${type}show`;setTimeout(()=>{toast.classList.remove('show');},3000);}
function updateStats(){document.getElementById('totalCount').textContent=allGames.length;document.getElementById('availableCount').textContent=allGames.filter(g=>g.status!=='借出').length;document.getElementById('borrowedCount').textContent=allGames.filter(g=>g.status==='借出').length;document.getElementById('unstockedCount').textContent=allGames.filter(g=>g.status==='未入庫').length;}
async function loadGames(){try{const[gamesResp,membersResp]=await Promise.all([fetch(`${apiBase}/games`),fetch(`${apiBase}/members`)]);if(!gamesResp.ok||!membersResp.ok)throw new Error('Server error');allGames=await gamesResp.json();allMembers=await membersResp.json();memberNameToId={};allMembers.forEach(member=>{const name=String(member.name||'').trim();const id=String(member.id||'').trim();if(name&&id){memberNameToId[name]=id;}});updateStats();applyCurrentFilter();const now=new Date();const timeString=now.toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'});const timeElement=document.getElementById('lastUpdateTime');if(timeElement){timeElement.textContent=`最後更新：${timeString}`;}}catch(e){console.error("載入失敗:",e);showToast('載入資料失敗','error');}}
function formatDate(timestamp){if(!timestamp)return'';const date=new Date(timestamp);return date.toLocaleDateString('zh-TW',{year:'numeric',month:'2-digit',day:'2-digit'});}
function renderTable(games){const tbody=document.querySelector('#gameTable tbody');tbody.innerHTML='';const isAdmin=document.body.classList.contains('admin-page');const fragment=document.createDocumentFragment();games.forEach(game=>{const tr=document.createElement('tr');if(game.status==='借出'){tr.classList.add('status-borrowed');}
let borrowerDisplay=game.borrower||'';if(game.status==='借出'&&game.borrower){borrowerDisplay=`<strong>${game.borrower}</strong>`;}
let checkboxHtml='';if(isAdmin){checkboxHtml=`<td><input type="checkbox"class="game-checkbox"value="${game.name}"></td>`;}
const statusText=game.status==='借出'?'借出':'在庫';const statusClass=game.status==='借出'?'status-borrowed':'status-available';const escapedName=String(game.name||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'").replace(/"/g,'&quot;').replace(/`/g,'\\`');const bggIcon=game.bgg_id?`<span class="bgg-linked"title="已連結到 BGG (ID: ${game.bgg_id})"onclick="viewBGGGameDetails(${game.bgg_id}, \`${escapedName}\`)">🔗</span>`:`<span class="bgg-not-linked"title="連結到 BGG"onclick="openBGGLinkModal(\`${escapedName}\`)">➕</span>`;const thumbnailHtml=game.bgg_thumbnail?`<img src="${game.bgg_thumbnail}"class="game-thumbnail"alt="縮圖"onclick="viewBGGGameDetails(${game.bgg_id}, \`${escapedName}\`)">`:'';tr.innerHTML=`${checkboxHtml}<td class="game-name-cell"><div class="game-name-wrapper">${thumbnailHtml}
${bggIcon}<span>${game.name}</span></div></td><td><span class="status-badge ${statusClass}"><span class="status-dot"></span>${statusText}</span></td><td>${borrowerDisplay}</td><td>${(()=>{let displayBorrowerId=game.borrower_id||'';if(!displayBorrowerId&&game.borrower){const borrowerName=String(game.borrower).trim();displayBorrowerId=memberNameToId[borrowerName]||'';}
return displayBorrowerId;})()}</td><td>${game.custodian||''}</td><td>${formatDate(game.mdate)}</td><td>${game.location||''}</td><td>${game.diff||''}</td><td>${game.players||''}</td>`;if(isAdmin){tr.addEventListener('dblclick',()=>{if(game.status==='借出'){executeSingleReturn(game.name);}else{executeSingleBorrow(game.name);}});}
fragment.appendChild(tr);});tbody.appendChild(fragment);const resultCountElement=document.getElementById('resultCount');if(resultCountElement){resultCountElement.textContent=`顯示 ${games.length}/總共 ${allGames.length}款桌遊`;}}
function executeSingleBorrow(gameName){const memberId=prompt(`借出桌遊：${gameName}\n請輸入工號：`);if(memberId){fetch('/api/borrow',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:gameName,member_id:memberId})}).then(r=>r.json()).then(data=>{if(data.success){showToast('借出成功');loadGames();}else{showToast(data.message||data.error,'error');}}).catch(err=>{showToast('借出失敗','error');console.error(err);});}}
function executeSingleReturn(gameName){if(confirm(`確定要歸還《${gameName}》嗎？`)){fetch('/api/return',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:gameName})}).then(r=>r.json()).then(data=>{if(data.success){showToast('歸還成功');loadGames();}else{showToast(data.message||data.error,'error');}}).catch(err=>{showToast('歸還失敗','error');console.error(err);});}}
function filterByStatus(status){currentStatusFilter=status;document.querySelectorAll('.filter-btn').forEach(btn=>{if(btn.dataset.filter===status)btn.classList.add('active');else btn.classList.remove('active');});applyCurrentFilter();}
function filterByPlayers(players){const btn=document.querySelector(`.player-btn[data-players="${players}"]`);if(currentPlayerFilters.has(players)){currentPlayerFilters.delete(players);btn.classList.remove('active');}else{currentPlayerFilters.add(players);btn.classList.add('active');}
applyCurrentFilter();}
function clearFilters(){currentStatusFilter='all';currentPlayerFilters.clear();document.querySelectorAll('.filter-btn').forEach(btn=>{if(btn.dataset.filter==='all')btn.classList.add('active');else btn.classList.remove('active');});document.querySelectorAll('.player-btn').forEach(btn=>{btn.classList.remove('active');});applyCurrentFilter();}
function applyCurrentFilter(){const filteredGames=allGames.filter(game=>{const statusMatch=currentStatusFilter==='all'||game.status===currentStatusFilter;const playerMatch=currentPlayerFilters.size===0||Array.from(currentPlayerFilters).every(filter=>matchesPlayerCount(game.players,filter));return statusMatch&&playerMatch;});renderTable(filteredGames);}
function matchesPlayerCount(gamePlayers,filterPlayers){if(!gamePlayers)return false;const parts=String(gamePlayers).split('-').map(p=>parseInt(p.trim()));const min=parts[0];const max=parts.length>1?parts[1]:min;if(filterPlayers==='10+')return max>=10;const target=parseInt(filterPlayers);return target>=min&&target<=max;}
function debounce(func,wait){let timeout;return function executedFunction(...args){const later=()=>{clearTimeout(timeout);func(...args);};clearTimeout(timeout);timeout=setTimeout(later,wait);};}
document.getElementById('searchBox').addEventListener('input',debounce((e)=>{const term=e.target.value.toLowerCase();const filtered=allGames.filter(game=>{const nameMatch=String(game.name||'').toLowerCase().includes(term);const borrowerMatch=String(game.borrower||'').toLowerCase().includes(term);const borrowerIdMatch=String(game.borrower_id||'').toLowerCase().includes(term);return nameMatch||borrowerMatch||borrowerIdMatch;});renderTable(filtered);},50));document.querySelectorAll('th[data-col]').forEach(th=>{th.addEventListener('click',()=>{const col=th.dataset.col;const isAsc=th.classList.contains('asc');document.querySelectorAll('th').forEach(t=>t.classList.remove('asc','desc'));th.classList.toggle('asc',!isAsc);th.classList.toggle('desc',isAsc);const sorted=[...allGames].sort((a,b)=>{const valA=String(a[col]||'');const valB=String(b[col]||'');return isAsc?valB.localeCompare(valA,'zh-Hant'):valA.localeCompare(valB,'zh-Hant');});renderTable(sorted);});});document.addEventListener('DOMContentLoaded',()=>{loadGames();document.querySelectorAll('.filter-btn').forEach(btn=>{btn.addEventListener('click',()=>filterByStatus(btn.dataset.filter));});document.querySelectorAll('.player-btn').forEach(btn=>{btn.addEventListener('click',()=>filterByPlayers(btn.dataset.players));});const clearBtn=document.getElementById('clearFiltersBtn');if(clearBtn){clearBtn.addEventListener('click',clearFilters);}
if(document.body.classList.contains('admin-page')){const gameTable=document.getElementById('gameTable');if(gameTable){gameTable.addEventListener('change',(e)=>{if(e.target.classList.contains('game-checkbox')){const checkedCount=document.querySelectorAll('.game-checkbox:checked').length;if(checkedCount>5){e.target.checked=false;showToast('單筆資料最多只能選5個','error');}
const allCheckboxes=document.querySelectorAll('.game-checkbox');const selectAll=document.getElementById('selectAll');if(selectAll){selectAll.checked=allCheckboxes.length>0&&checkedCount===allCheckboxes.length;}}});}
const selectAll=document.getElementById('selectAll');if(selectAll){selectAll.addEventListener('click',(e)=>{const checkboxes=document.querySelectorAll('.game-checkbox');const isChecked=e.target.checked;if(isChecked){let count=0;checkboxes.forEach(cb=>{if(count<5){cb.checked=true;count++;}else{cb.checked=false;}});if(checkboxes.length>5){showToast('已自動選取前5筆 (單筆上限5個)','warning');}}else{checkboxes.forEach(cb=>cb.checked=false);}});}
const batchBorrowBtn=document.getElementById('batchBorrowBtn');if(batchBorrowBtn){batchBorrowBtn.addEventListener('click',(e)=>{e.preventDefault();const selected=Array.from(document.querySelectorAll('.game-checkbox:checked')).map(cb=>cb.value);if(selected.length===0)return showToast('請選擇桌遊','error');const memberId=prompt(`將借出 ${selected.length}款桌遊，請輸入工號：`);if(!memberId)return;fetch('/api/batch-borrow',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({game_names:selected,member_id:memberId})}).then(r=>r.json()).then(data=>{if(data.success){showToast('批次借出成功');loadGames();if(selectAll)selectAll.checked=false;}else{showToast(data.message||data.error,'error');}});});}
const batchReturnBtn=document.getElementById('batchReturnBtn');if(batchReturnBtn){batchReturnBtn.addEventListener('click',(e)=>{e.preventDefault();const selected=Array.from(document.querySelectorAll('.game-checkbox:checked')).map(cb=>cb.value);if(selected.length===0)return showToast('請選擇桌遊','error');if(confirm(`確定要歸還 ${selected.length}款桌遊？`)){fetch('/api/batch-return',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({game_names:selected})}).then(r=>r.json()).then(data=>{if(data.success){showToast('批次歸還成功');loadGames();if(selectAll)selectAll.checked=false;}else{showToast(data.message||data.error,'error');}});}});}}
setInterval(loadGames,1800000);});function cleanGameNameForBGGSearch(gameName){let cleaned=gameName.trim();cleaned=cleaned.replace(/[\s-_]*[A-Za-z]$/,'');cleaned=cleaned.replace(/[\s-_]*\d+$/,'');cleaned=cleaned.split(/[-_]/)[0].trim();return cleaned;}
function openBGGLinkModal(gameName){const cleanedName=cleanGameNameForBGGSearch(gameName);const modal=document.createElement('div');modal.className='bgg-modal';modal.id='bggLinkModal';modal.innerHTML=`<div class="bgg-modal-content"><span class="bgg-modal-close"onclick="closeBGGLinkModal()">&times;</span><h2>連結「${gameName}」到 BGG</h2><div class="bgg-search-box"><label>搜尋關鍵字：</label><div class="search-input-group"><input type="text"id="bggSearchInput"value="${cleanedName}"placeholder="輸入搜尋關鍵字"><button class="btn small primary"onclick="manualSearchBGG('${gameName}')">搜尋</button></div><p class="search-hint">💡 提示：如找不到，請嘗試英文原名或簡化名稱</p></div><div class="bgg-link-search"><p>正在搜尋 BoardGameGeek...</p><div id="bggLinkResults"></div></div></div>`;document.body.appendChild(modal);searchAndLinkBGG(gameName,cleanedName);}
function closeBGGLinkModal(){const modal=document.getElementById('bggLinkModal');if(modal){modal.remove();}}
async function searchAndLinkBGG(originalGameName,searchQuery=null){try{const query=searchQuery||cleanGameNameForBGGSearch(originalGameName);const response=await fetch(`/api/bgg/games/link/search/${encodeURIComponent(query)}`);const data=await response.json();if(data.success&&data.results&&data.results.length>0){displayBGGLinkResults(originalGameName,data.results);}else{document.getElementById('bggLinkResults').innerHTML=`<p class="no-results">找不到「${query}」相關的 BGG 桌遊。<br>請嘗試修改搜尋關鍵字或使用英文名稱。</p>`;}}catch(error){console.error('BGG search error:',error);document.getElementById('bggLinkResults').innerHTML='<p class="error">搜尋時發生錯誤，請稍後再試。</p>';}}
function displayBGGLinkResults(gameName,results){const resultsDiv=document.getElementById('bggLinkResults');resultsDiv.innerHTML='<h3>選擇要連結的桌遊：</h3>';results.forEach(game=>{const card=document.createElement('div');card.className='bgg-link-card';const escapedGameName=gameName.replace(/\\/g,'\\\\').replace(/'/g,"\\'").replace(/"/g,'&quot;');const escapedBggName=game.name.replace(/\\/g,'\\\\').replace(/'/g,"\\'").replace(/"/g,'&quot;');card.innerHTML=`<div class="bgg-link-info"><h4>${game.name}</h4><p>年份:${game.year||'N/A'}|ID:${game.id}</p></div><button class="btn small primary"onclick="linkGameToBGG('${escapedGameName}', ${game.id}, '${escapedBggName}')">選擇此遊戲</button>`;resultsDiv.appendChild(card);});}
function manualSearchBGG(originalGameName){const searchInput=document.getElementById('bggSearchInput');const searchQuery=searchInput.value.trim();if(!searchQuery){alert('請輸入搜尋關鍵字');return;}
document.getElementById('bggLinkResults').innerHTML='<p>正在搜尋...</p>';searchAndLinkBGG(originalGameName,searchQuery);}
async function linkGameToBGG(gameName,bggId,bggName){if(!confirm(`確定要將「${gameName}」連結到 BGG 的「${bggName}」(ID:${bggId})嗎？`)){return;}
try{const response=await fetch(`/api/bgg/games/link/${encodeURIComponent(gameName)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({bgg_id:bggId})});const data=await response.json();if(data.success){showToast('✅ 連結成功！');closeBGGLinkModal();loadGames();}else{showToast(data.error||'連結失敗','error');}}catch(error){console.error('Link error:',error);showToast('連結時發生錯誤','error');}}